  uint8_t object[40];const char*text;if(!nflstreet_ui_text_find(screen,screen_size,0x01000000,choices[k],0,object,&text)||object[2]!=3||object[3]!=2||!nflstreet_ui_text_prepare(object,&font,text))return 0;
  float context[8];for(unsigned i=0;i<4;++i){context[i]=fl(screen+root+0x3c+i*4);context[4+i]=fl(screen+root+0x4c+i*4);if(!isfinite(context[i])||!isfinite(context[4+i]))return 0;}nflstreet_ui_text_plan plan;nflstreet_glyph_box glyphs[354];unsigned count;
