  if(plan.visible)for(unsigned pass=0;pass<2;++pass)for(unsigned g=0;g<count;++g){const nflstreet_glyph_box*box=glyphs+g;for(unsigned y=0;y<box->height;++y)for(unsigned x=0;x<box->width;++x)pixel((int)(rx+plan.position[0])+box->x+x,(int)(ry+plan.position[1])+box->y+y,atlas[pass].bgra[(box->v+y)*atlas[pass].width+box->u+x],plan.color[pass?0:1]);}
