 if(argc==7){const unsigned sequence[]={0,0,1,0},modes[]={1,0,2,0};unsigned captures=0;for(unsigned phase=0;phase<4;++phase){if(!(phase&1)&&!select_choice(sequence[phase]))return 5;if(!control_choice(phase&1?6:7))return 5;for(unsigned frame=0;frame<=160;++frame){if(frame&&!advance_menu())return 5;if(frame==0||frame==4||frame==20||frame==32||frame==52||frame==53||frame==80||frame==160){char name[4096];snprintf(name,sizeof name,"%s-%u-%03u.bmp",argv[5],phase,frame);if(!nflstreet_texture_bmp(&canvas,name))return 5;++captures;}}if(be(screen+0x960+0x80)!=modes[phase]||menu.entry_flags||menu.rates.count)return 5;}printf("Native transition captures passed:4 supplied-context confirm/back cycles,640 source updates,%u captures; external profile/screen startup and original PAD routing unfinished\n",captures);return 0;}
